v_readfirstlane_b32 s16, v0                        // quotient
s_mov_b32 s[sgprWorkGroup1], s16
/* wg0 = idxWG01 - wg1 * numWG0 */
s_mul_i32 s16, s16, s[sgprNumWorkGroups0]
