s_lshr_b32 s20, s32, 8                             // s20 = s32 / 256
s_and_b32 s18, 255, s32                            // s18 = s32 % 256
s_addc_u32 s20, s20, 0
s_lshr_b32 s21, s33, 8                             // s21 = s33 / 256
s_and_b32 s18, 255, s33                            // s18 = s33 % 256
s_addc_u32 s21, s21, 0
