s_set_vgpr_msb 35464                               // src0: 0, src1: 2, src2: 0, dst: 2
v_add_nc_u32 v[vgprLocalReadSwapAddrB-512], 132096, v[vgprLocalReadAddrB-512] // Calculate starting lds addr of second buffer
s_set_vgpr_msb 34954                               // src0: 2, src1: 2, src2: 0, dst: 2
